    'hsr': { n: 'Treliça de separação', t: 'Treliça integrada de separação a quente', d: 'A Ship acende os motores ainda presa ao propulsor. O Block 3 troca o antigo anel ventilado separado por uma treliça aberta de hastes em V integrada ao propulsor. O escape da Ship passa entre as hastes e atinge diretamente a cúpula superior do propulsor.', s: [['Projeto', 'Treliça em V'], ['Descarte', 'Nenhum'], ['Desde', 'Voo 12']] },
    's-raptors': { n: 'Motores da Ship', t: 'Motores Raptor da Ship', d: 'Três Raptors de nível do mar no centro se orientam para dirigir e pousar. Ao redor deles, três Raptor Vacuum com grandes extensões fixas de bocal fornecem o empuxo mais eficiente necessário no espaço.', s: [['Nível do mar', '3'], ['Vácuo', '3'], ['Saída RVac', '{rvacExit}']] },
    's-tanks': { n: 'Tanques da Ship', t: 'Tanques de propelente da Ship', d: 'A Ship leva seu próprio oxigênio e metano em dois tanques principais; no Block 3 a cúpula comum e a inferior foram rebaixadas para caber mais metano. O metano chega aos motores por downcomers que atravessam o tanque de oxigênio: um compartilhado pelos três motores de nível do mar e um dedicado a cada Raptor Vacuum. Pequenos tanques de cabeçalho mantêm o propelente de pouso estável quando os principais estão quase vazios.', s: [['Tanques principais', '2'], ['Downcomers', '4'], ['Cabeçalho', '2']] },
