    's-payload': { n: 'Compartimento de carga', t: 'Compartimento de carga e fenda Pez', d: 'Nos voos {starlink} os satélites ficam empilhados no compartimento de carga. Uma fenda horizontal longa e estreita, apelidada de "dispensador Pez", abre no lado de sotavento, e os satélites deslizam por ela um de cada vez.', s: [['Porta', 'Fenda'], ['Carga útil', '{payload}'], ['Carga', '{starlink}']] },
