    's-flaps': { n: 'Flaps', t: 'Voorste en achterste flaps', d: 'Vier flaps werken als de armen van een parachutist. Tijdens de "bellyflop"-afdaling regelen ze de stand van Ship, tot hij rechtop kantelt en zijn motoren ontsteekt om te landen.', s: [['Aantal', '4'], ['Aandrijving', 'Elektrisch'], ['Modus', 'Bellyflop']] },
    's-payload': { n: 'Laadruim', t: 'Laadruim en Pez-sleuf', d: 'Op {starlink}-vluchten liggen de satellieten gestapeld in het laadruim. Een lange, smalle horizontale sleuf, de "Pez-dispenser" genoemd, gaat open aan de lijzijde en de satellieten schuiven er één voor één uit.', s: [['Deur', 'Brievenbussleuf'], ['Nuttige last', '{payload}'], ['Vracht', '{starlink}']] },
